def word_break(s, word_dict):
    word_set = set(word_dict)

    def helper(start):
        if start == len(s):
            return [""]
        sentences = []
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in word_set:
                for rest in helper(end):                            # recomputes this suffix every time it recurs
                    sentence = word if rest == "" else word + " " + rest
                    sentences.append(sentence)
        return sentences

    return helper(0)


if __name__ == "__main__":
    s = "catsanddog"
    word_dict = ["cat", "cats", "and", "sand", "dog"]
    print(word_break(s, word_dict))

