#include <bits/stdc++.h>
using namespace std;

vector<string> helper(const string& s, int start, unordered_set<string>& wordSet,
                       unordered_map<int, vector<string>>& memo) {
    auto it = memo.find(start);
    if (it != memo.end()) return it->second;                            // reuse a suffix already solved before
    if (start == (int)s.size()) return memo[start] = {""};
    vector<string> sentences;
    for (int end = start + 1; end <= (int)s.size(); end++) {
        string word = s.substr(start, end - start);
        if (wordSet.count(word)) {
            for (string& rest : helper(s, end, wordSet, memo)) {
                sentences.push_back(rest.empty() ? word : word + " " + rest);
            }
        }
    }
    return memo[start] = sentences;
}

vector<string> wordBreak(string s, vector<string>& wordDict) {
    unordered_set<string> wordSet(wordDict.begin(), wordDict.end());
    unordered_map<int, vector<string>> memo;
    return helper(s, 0, wordSet, memo);
}

int main() {
    string s = "catsanddog";
    vector<string> wordDict = {"cat", "cats", "and", "sand", "dog"};
    vector<string> result = wordBreak(s, wordDict);
    for (auto& sentence : result) cout << "\"" << sentence << "\" ";
    cout << endl;
    return 0;
}
